using Marina.Domain.Catalog; using Marina.Domain.Commerce; using Marina.Domain.Security; using Marina.Persistence.Identity; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Marina.Persistence.Data;
public sealed class CategoryConfiguration:IEntityTypeConfiguration<Category>{public void Configure(EntityTypeBuilder<Category>b){b.HasIndex(x=>x.Slug).IsUnique();b.Property(x=>x.Slug).HasMaxLength(160);b.HasOne(x=>x.Parent).WithMany(x=>x.Children).HasForeignKey(x=>x.ParentId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TranslationConfiguration:IEntityTypeConfiguration<ProductTranslation>,IEntityTypeConfiguration<CategoryTranslation>,IEntityTypeConfiguration<BrandTranslation>{public void Configure(EntityTypeBuilder<ProductTranslation>b){b.HasIndex(x=>new{x.ProductId,x.Culture}).IsUnique();b.Property(x=>x.Culture).HasMaxLength(10);b.Property(x=>x.Name).HasMaxLength(240);}public void Configure(EntityTypeBuilder<CategoryTranslation>b){b.HasIndex(x=>new{x.CategoryId,x.Culture}).IsUnique();b.Property(x=>x.Culture).HasMaxLength(10);b.Property(x=>x.Name).HasMaxLength(160);}public void Configure(EntityTypeBuilder<BrandTranslation>b){b.HasIndex(x=>new{x.BrandId,x.Culture}).IsUnique();b.Property(x=>x.Culture).HasMaxLength(10);b.Property(x=>x.Name).HasMaxLength(160);}}
public sealed class ProductConfiguration:IEntityTypeConfiguration<Product>{public void Configure(EntityTypeBuilder<Product>b){b.HasIndex(x=>x.Slug).IsUnique();b.Property(x=>x.Slug).HasMaxLength(180);b.Property(x=>x.RowVersion).IsRowVersion();}}
public sealed class VariantConfiguration:IEntityTypeConfiguration<ProductVariant>{public void Configure(EntityTypeBuilder<ProductVariant>b){b.HasIndex(x=>x.Sku).IsUnique();b.HasIndex(x=>x.Barcode).IsUnique().HasFilter("[Barcode] IS NOT NULL");b.HasIndex(x=>new{x.ProductId,x.ColorId,x.SizeId}).IsUnique().HasFilter(null);b.ToTable(t=>t.HasCheckConstraint("CK_Variant_Prices","[Price] >= 0 AND ([CompareAtPrice] IS NULL OR [CompareAtPrice] >= 0)"));b.Property(x=>x.Sku).HasMaxLength(80);b.Property(x=>x.Price).HasPrecision(18,2);b.Property(x=>x.CompareAtPrice).HasPrecision(18,2);b.Property(x=>x.RowVersion).IsRowVersion();b.HasOne(x=>x.Inventory).WithOne().HasForeignKey<Inventory>(x=>x.ProductVariantId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class InventoryConfiguration:IEntityTypeConfiguration<Inventory>{public void Configure(EntityTypeBuilder<Inventory>b){b.HasIndex(x=>x.ProductVariantId).IsUnique();b.Property(x=>x.RowVersion).IsRowVersion();b.ToTable(t=>t.HasCheckConstraint("CK_Inventory_Quantity","[Quantity] >= 0 AND [ReservedQuantity] >= 0 AND [ReservedQuantity] <= [Quantity]"));}}
public sealed class CartConfiguration:IEntityTypeConfiguration<Cart>,IEntityTypeConfiguration<CartItem>{public void Configure(EntityTypeBuilder<Cart>b){b.HasIndex(x=>x.UserId).IsUnique();b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);}public void Configure(EntityTypeBuilder<CartItem>b){b.HasIndex(x=>new{x.CartId,x.VariantId}).IsUnique();b.HasOne(x=>x.Cart).WithMany(x=>x.Items).HasForeignKey(x=>x.CartId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.Variant).WithMany().HasForeignKey(x=>x.VariantId).OnDelete(DeleteBehavior.Restrict);b.ToTable(t=>t.HasCheckConstraint("CK_CartItem_Quantity","[Quantity] > 0 AND [Quantity] <= 20"));}}
public sealed class CustomerRelationshipConfiguration:IEntityTypeConfiguration<Address>,IEntityTypeConfiguration<Favorite>,IEntityTypeConfiguration<Notification>,IEntityTypeConfiguration<StockMovement>,IEntityTypeConfiguration<CouponUsage>{public void Configure(EntityTypeBuilder<Address>b){b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.UserId,x.IsDefault});b.HasIndex(x=>x.UserId).IsUnique().HasFilter("[IsDefault] = 1 AND [IsDeleted] = 0");}public void Configure(EntityTypeBuilder<Favorite>b){b.HasIndex(x=>new{x.UserId,x.ProductId}).IsUnique();b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);b.HasOne<Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Cascade);}public void Configure(EntityTypeBuilder<Notification>b){b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.UserId,x.ReadUtc,x.CreatedUtc});}public void Configure(EntityTypeBuilder<StockMovement>b){b.HasOne<ProductVariant>().WithMany().HasForeignKey(x=>x.VariantId).OnDelete(DeleteBehavior.Restrict);b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.ActorId).OnDelete(DeleteBehavior.NoAction);}public void Configure(EntityTypeBuilder<CouponUsage>b){b.HasIndex(x=>new{x.CouponId,x.UserId,x.OrderId}).IsUnique();b.HasOne<Coupon>().WithMany().HasForeignKey(x=>x.CouponId).OnDelete(DeleteBehavior.Restrict);b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Order>().WithMany().HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class CatalogRelationshipConfiguration:IEntityTypeConfiguration<ProductImage>,IEntityTypeConfiguration<OrderStatusHistory>{public void Configure(EntityTypeBuilder<ProductImage>b){b.HasOne<Product>().WithMany(x=>x.Images).HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Cascade);b.HasOne<ProductVariant>().WithMany().HasForeignKey(x=>x.VariantId).OnDelete(DeleteBehavior.NoAction);b.HasIndex(x=>new{x.ProductId,x.SortOrder}).IsUnique();}public void Configure(EntityTypeBuilder<OrderStatusHistory>b){b.HasOne<Order>().WithMany(x=>x.StatusHistory).HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.Cascade);b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.ActorId).OnDelete(DeleteBehavior.NoAction);b.HasIndex(x=>new{x.OrderId,x.CreatedUtc});}}
public sealed class OrderConfiguration:IEntityTypeConfiguration<Order>,IEntityTypeConfiguration<OrderItem>{public void Configure(EntityTypeBuilder<Order>b){b.HasIndex(x=>x.PublicNumber).IsUnique();b.HasIndex(x=>new{x.UserId,x.IdempotencyKey}).IsUnique();b.Property(x=>x.RowVersion).IsRowVersion();b.Property(x=>x.PublicNumber).HasMaxLength(40);b.Property(x=>x.IdempotencyKey).HasMaxLength(100);b.ToTable(t=>t.HasCheckConstraint("CK_Order_Amounts","[Subtotal] >= 0 AND [Discount] >= 0 AND [Shipping] >= 0 AND [Tax] >= 0 AND [Total] >= 0"));b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Address>().WithMany().HasForeignKey(x=>x.AddressId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Coupon>().WithMany().HasForeignKey(x=>x.CouponId).OnDelete(DeleteBehavior.SetNull);foreach(var p in new[]{nameof(Order.Subtotal),nameof(Order.Discount),nameof(Order.Shipping),nameof(Order.Tax),nameof(Order.Total)})b.Property(p).HasPrecision(18,2);}public void Configure(EntityTypeBuilder<OrderItem>b){b.HasOne<Order>().WithMany(x=>x.Items).HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.Variant).WithMany().HasForeignKey(x=>x.VariantId).OnDelete(DeleteBehavior.Restrict);b.ToTable(t=>t.HasCheckConstraint("CK_OrderItem_Values","[Quantity] >= 1 AND [Quantity] <= 20 AND [UnitPrice] >= 0 AND [Discount] >= 0"));b.Property(x=>x.UnitPrice).HasPrecision(18,2);b.Property(x=>x.Discount).HasPrecision(18,2);}}
public sealed class CouponConfiguration:IEntityTypeConfiguration<Coupon>{public void Configure(EntityTypeBuilder<Coupon>b){b.HasIndex(x=>x.Code).IsUnique();b.Property(x=>x.RowVersion).IsRowVersion();b.Property(x=>x.Code).HasMaxLength(40);b.ToTable(t=>t.HasCheckConstraint("CK_Coupon_Values","[Type] IN (0,1) AND [Value] >= 0 AND ([Type] <> 0 OR [Value] <= 100) AND ([MinimumPurchase] IS NULL OR [MinimumPurchase] >= 0) AND ([MaximumDiscount] IS NULL OR [MaximumDiscount] >= 0) AND [ValidToUtc] >= [ValidFromUtc] AND ([MaxUses] IS NULL OR [MaxUses] > 0) AND ([MaxUsesPerCustomer] IS NULL OR [MaxUsesPerCustomer] > 0)"));b.Property(x=>x.Value).HasPrecision(18,2);b.Property(x=>x.MinimumPurchase).HasPrecision(18,2);b.Property(x=>x.MaximumDiscount).HasPrecision(18,2);}}
public sealed class SecurityConfiguration:IEntityTypeConfiguration<Permission>,IEntityTypeConfiguration<RolePermission>,IEntityTypeConfiguration<UserSession>,IEntityTypeConfiguration<RefreshToken>{public void Configure(EntityTypeBuilder<Permission>b){b.HasIndex(x=>x.Name).IsUnique();b.Property(x=>x.Name).HasMaxLength(100);}public void Configure(EntityTypeBuilder<RolePermission>b){b.HasIndex(x=>new{x.RoleId,x.PermissionId}).IsUnique();b.HasOne<IdentityRole<Guid>>().WithMany().HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Cascade);b.HasOne<Permission>().WithMany().HasForeignKey(x=>x.PermissionId).OnDelete(DeleteBehavior.Cascade);}public void Configure(EntityTypeBuilder<UserSession>b){b.HasIndex(x=>new{x.UserId,x.RevokedUtc});b.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);}public void Configure(EntityTypeBuilder<RefreshToken>b){b.HasIndex(x=>x.TokenHash).IsUnique();b.Property(x=>x.TokenHash).HasMaxLength(64);b.HasOne(x=>x.UserSession).WithMany(x=>x.RefreshTokens).HasForeignKey(x=>x.UserSessionId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class PaymentConfiguration:IEntityTypeConfiguration<Payment>,IEntityTypeConfiguration<PaymentTransaction>{public void Configure(EntityTypeBuilder<Payment>b){b.HasIndex(x=>new{x.OrderId,x.Provider,x.IdempotencyKey}).IsUnique();b.HasIndex(x=>new{x.OrderId,x.Provider}).IsUnique().HasFilter("[Provider] = 'CashOnDelivery'");b.Property(x=>x.IdempotencyKey).HasMaxLength(100);b.Property(x=>x.Provider).HasMaxLength(60);b.HasOne<Order>().WithMany().HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.Amount).HasPrecision(18,2);b.ToTable(t=>t.HasCheckConstraint("CK_Payment_Amount","[Amount] >= 0"));}public void Configure(EntityTypeBuilder<PaymentTransaction>b){b.HasIndex(x=>new{x.PaymentId,x.ProviderReference,x.EventType}).IsUnique();b.HasIndex(x=>x.PayloadHash).IsUnique();b.Property(x=>x.PayloadHash).HasMaxLength(80);}}
